package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public class PerceptionTest {
    static BufferedImage photo(String name) throws Exception {try(var in=PerceptionTest.class.getResourceAsStream("/perception/"+name+".png")){return ImageIO.read(in);}}
    static BufferedImage scene(int x,int y,double scale,boolean hidden) throws Exception {var image=new BufferedImage(320,250,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(new Color(0x233b50));g.fillRect(0,0,320,250);if(!hidden)g.drawImage(photo("astronaut"),x,y,(int)(160*scale),(int)(160*scale),null);g.dispose();return image;}
    static PixelTracker.Box truth(int x,int y,double scale){return new PixelTracker.Box((x+12*160/512.*scale)/320,(y+14*160/512.*scale)/250,(376-12)*160/512.*scale/320,(512-14)*160/512.*scale/250);}
    static JSONObject packet(BufferedImage image,String page,String ref,long time) throws Exception {var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return new JSONObject().put("id",UUID.randomUUID().toString()).put("png",Base64.getEncoder().encodeToString(out.toByteArray())).put("source",new JSONObject().put("pageId",page).put("ref",ref).put("kind","canvas").put("label","Page claims a cup; pixel content must be checked separately").put("url","http://localhost/fixture").put("signature","a".repeat(64)).put("crop",new JSONObject().put("x",20).put("y",30).put("width",320).put("height",250)).put("scrollX",0).put("scrollY",0).put("capturedAt",time).put("width",320).put("height",250));}
    @Test public void boundedRealImageDecoderAndBoxValidation() throws Exception {var image=scene(35,30,1,false);var p=packet(image,UUID.randomUUID().toString(),"1",1000);assertEquals(320,PerceptionStore.decode(Base64.getDecoder().decode(p.getString("png"))).getWidth());assertThrows(Exception.class,()->PerceptionStore.decode(new byte[1_000_001]));assertThrows(Exception.class,()->PerceptionStore.decode(new byte[]{1,2,3}));assertThrows(IllegalArgumentException.class,()->PixelTracker.Box.from(new JSONArray(new double[]{.5,.5,.4,.4})));assertThrows(IllegalArgumentException.class,()->PixelTracker.Box.from(new JSONArray(new double[]{-.1,0,.4,.4})));}
    @Test public void javaTrackerFollowsRealPixelsAndRejectsOcclusion() throws Exception {var tracker=new PixelTracker(UUID.randomUUID().toString(),"person",scene(35,30,1,false),truth(35,30,1),true);for(int x:new int[]{40,46,53,61}){var update=tracker.update(scene(x,35,1,false));assertNotEquals(update.toString(),"lost",update.getString("status"));assertTrue(update.toString(),PixelTracker.iou(truth(x,35,1),PixelTracker.Box.from(update.getJSONArray("box")))>.7);}var lost=tracker.update(scene(0,0,1,true));assertEquals("lost",lost.getString("status"));assertTrue(lost.isNull("box"));var found=tracker.update(scene(90,42,1,false));assertEquals(found.toString(),"reacquired",found.getString("status"));assertTrue(PixelTracker.iou(truth(90,42,1),PixelTracker.Box.from(found.getJSONArray("box")))>.7);}
    @Test public void ambiguousDuplicateAppearanceDoesNotInventIdentity() throws Exception {var seed=scene(35,30,1,false);var tracker=new PixelTracker("track","person",seed,truth(35,30,1),false);var image=new BufferedImage(640,250,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(new Color(0x233b50));g.fillRect(0,0,640,250);g.drawImage(photo("astronaut"),30,30,160,160,null);g.drawImage(photo("astronaut"),350,30,160,160,null);g.dispose();var result=tracker.update(image);assertEquals(result.toString(),"lost",result.getString("status"));}
    @Test public void explicitTeachingSurvivesRestartAndRecognizesChangedView() throws Exception {var root=Files.createTempDirectory("perception-teaching");String lessonId;var initial=scene(35,30,1,false);try(var store=new PerceptionStore(root)){var f=store.frame(packet(initial,UUID.randomUUID().toString(),"1",1000));var l=store.teach(new JSONObject().put("frameId",f.getString("id")).put("box",truth(35,30,1).json()).put("label","person").put("name","real-appearance"));lessonId=l.getString("id");assertEquals(1,l.getInt("version"));assertEquals(0,store.state().getJSONArray("runs").length());}
        try(var store=new PerceptionStore(root)){var l=store.lesson(lessonId);var tracker=new PixelTracker("later",l.getString("label"),PixelTracker.learned(l),PixelTracker.Box.from(l.getJSONArray("box")),false);var result=tracker.update(scene(80,50,.8,false));assertNotEquals(result.toString(),"lost",result.getString("status"));assertTrue(result.toString(),PixelTracker.iou(truth(80,50,.8),PixelTracker.Box.from(result.getJSONArray("box")))>.7);}}
    @Test public void immutableFrameIdentityAndPrivateSourceValidation() throws Exception {try(var store=new PerceptionStore(Files.createTempDirectory("perception-source"))){var p=packet(scene(35,30,1,false),UUID.randomUUID().toString(),"1",1000);var f=store.frame(p);assertTrue(f.similar(store.frame(p)));p.getJSONObject("source").put("capturedAt",2000);assertThrows(IllegalStateException.class,()->store.frame(p));assertThrows(IllegalArgumentException.class,()->store.frame("../../private"));var q=packet(scene(35,30,1,false),UUID.randomUUID().toString(),"2",2000);q.getJSONObject("source").put("url","file:///private");assertThrows(IllegalArgumentException.class,()->store.frame(q));}}
    @Test public void lostMetricsNeverHaveAVisibleBoxAndQualityRemainsQualified(){var sample=new JSONObject().put("objects",new JSONArray().put(new JSONObject().put("status","lost").put("box",JSONObject.NULL).put("matchScore",0)));var r=new JSONObject().put("mode","vision").put("samples",new JSONArray().put(sample));var m=PerceptionStore.metrics(r);assertFalse(m.getBoolean("passed"));assertEquals(1,m.getInt("lostObservations"));assertFalse(m.getBoolean("semanticGroundTruthVerified"));sample.getJSONArray("objects").getJSONObject(0).put("box",new JSONArray(new double[]{0,0,.5,.5}));assertThrows(IllegalStateException.class,()->PerceptionStore.metrics(r));}
    static void tracking(PerceptionStore store,String id) throws Exception {for(int i=0;i<100;i++){if(store.run(id).getString("status").equals("tracking"))return;Thread.sleep(10);}fail("Real DOM tracker did not start");}
    @Test public void sourceAndSequenceFencesRejectForeignOrRepeatedSamples() throws Exception {try(var store=new PerceptionStore(Files.createTempDirectory("perception-fences"))){String page=UUID.randomUUID().toString();var f=store.frame(packet(scene(35,30,1,false),page,"1",1000));String id=UUID.randomUUID().toString();store.start(id,"goal",1,f.getString("id"),"dom","person","","",2);tracking(store,id);var next=store.frame(packet(scene(35,30,1,false),page,"1",2000));var sample=store.sample(id,1,next.getString("id"));assertTrue(sample.similar(store.sample(id,1,next.getString("id"))));assertThrows(IllegalStateException.class,()->store.sample(id,2,next.getString("id")));var foreign=store.frame(packet(scene(35,30,1,false),UUID.randomUUID().toString(),"1",3000));assertThrows(IllegalStateException.class,()->store.sample(id,2,foreign.getString("id")));assertThrows(IllegalStateException.class,()->store.sample(id,3,next.getString("id")));store.cancel(id);assertFalse(store.busy());assertEquals("cancelled",store.run(id).getString("status"));}}
    @Test public void completedFrameEvidenceReconstructsAndDetectsTampering() throws Exception {var root=Files.createTempDirectory("perception-evidence");try(var store=new PerceptionStore(root)){String page=UUID.randomUUID().toString();var f=store.frame(packet(scene(35,30,1,false),page,"1",1000));String id=UUID.randomUUID().toString();store.start(id,"goal",1,f.getString("id"),"dom","person","","",2);tracking(store,id);String last="";for(int i=1;i<=4;i++){var next=store.frame(packet(scene(35+i,30,1,false),page,"1",1000+i*1000));last=next.getString("id");store.sample(id,i,last);}assertTrue(store.finish(id).getJSONObject("metrics").getBoolean("passed"));assertEquals(4,store.verify(id).getInt("lastSequence"));Files.write(root.resolve("perception/frames").resolve(last+".png"),new byte[]{1,2});assertThrows(IllegalStateException.class,()->store.verify(id));}}
    @Test public void interruptedCaptureIsNotSilentlyResumedAfterRestart() throws Exception {var root=Files.createTempDirectory("perception-restart");String id=UUID.randomUUID().toString();try(var store=new PerceptionStore(root)){var f=store.frame(packet(scene(35,30,1,false),UUID.randomUUID().toString(),"1",1000));store.start(id,"goal",1,f.getString("id"),"dom","person","","",2);tracking(store,id);}try(var store=new PerceptionStore(root)){assertEquals("interrupted",store.run(id).getString("status"));assertFalse(store.busy());}}
    @Test public void failedHostCaptureReleasesOwnedResourcesForRecovery() throws Exception {var root=Files.createTempDirectory("perception-host-failure");try(var artifacts=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var spatial=new SpatialStore(root);var perception=new PerceptionStore(root);var goals=new GoalRunner(root,scenes,brain,artifacts,new MeasurementStore(root),spatial,perception)){var f=perception.frame(packet(scene(35,30,1,false),UUID.randomUUID().toString(),"1",1000));var g=goals.startPerception(new JSONObject().put("frameId",f.getString("id")).put("mode","dom").put("seconds",2));for(int i=0;i<200&&!goals.read(g.getString("id")).getString("status").equals("waiting-host");i++)Thread.sleep(10);assertTrue(goals.ownsBrowser());assertFalse(goals.ownsPhysics());var claim=goals.claim();assertEquals("browser.perception.sample",claim.getString("kind"));var stopped=goals.acknowledge(new JSONObject().put("goalId",g.getString("id")).put("id",claim.getString("id")).put("nonce",claim.getString("nonce")).put("error","Browser source changed"));assertEquals("interrupted",stopped.getString("status"));assertFalse(perception.busy());assertFalse(goals.ownsBrowser());assertEquals("cancelled",perception.run(goals.read(g.getString("id")).getString("runId")).getString("status"));}}
    @Test public void genericRegionProposalsPreserveFullImagesAndFindFlatBackgroundIslands() throws Exception {var proposals=PixelRegions.propose(scene(60,40,1,false));assertFalse(proposals.isEmpty());assertTrue(proposals.get(0).contains(100,100));assertTrue(proposals.get(0).width<250);var full=PixelRegions.propose(photo("astronaut"));assertEquals(1,full.size());assertEquals(512,full.get(0).width);assertTrue(PixelRegions.propose(scene(0,0,1,true)).isEmpty());}
}
